mapper.select:
select u.user_id, u.nick_name from sys_user u join sys_dept d on d.dept_id = u.dept_id
and u.del_flag = '0' and u.status = #{status} ${params.dataScope}
order by u.nick_name asc, u.user_id asc

select u.user_id, u.nick_name as label, u.dept_id, d.dept_name, ( select group_concat(path_dept.dept_name order by find_in_set(path_dept.dept_id, concat(d.ancestors, ',', d.dept_id)) separator ' / ') from sys_dept path_dept where path_dept.del_flag = '0' and find_in_set(path_dept.dept_id, concat(d.ancestors, ',', d.dept_id)) ) as dept_path, p.employee_no, case when u.phonenumber is null or u.phonenumber = '' then null when char_length(u.phonenumber) < 7 then '***' else concat(left(u.phonenumber, 3), '****', right(u.phonenumber, 4)) end as phone_masked from sys_user u join sys_dept d on d.dept_id = u.dept_id left join sys_user_profile p on p.user_id = u.user_id
and u.del_flag = '0' and u.status = '0' and d.del_flag = '0' and d.status = '0' ${params.dataScope}
and ( u.user_id in
#{userId}
or ( 1 = 1
and ( u.nick_name like concat('%', #{keyword}, '%') or p.employee_no like concat('%', #{keyword}, '%') or u.phonenumber like concat('%', #{keyword}, '%') )
and ( u.dept_id = #{deptId}
or find_in_set(#{deptId}, d.ancestors)
)
) )
and ( u.nick_name like concat('%', #{keyword}, '%') or p.employee_no like concat('%', #{keyword}, '%') or u.phonenumber like concat('%', #{keyword}, '%') )
and ( u.dept_id = #{deptId}
or find_in_set(#{deptId}, d.ancestors)
)
order by
case
when u.user_id = #{userId} then #{index}
else 999 end,
u.nick_name asc, u.user_id asc

select o.*, owner.nick_name as owner_name
from hr_onboarding o
join sys_dept d on d.dept_id = o.target_dept_id
left join sys_user owner on owner.user_id = o.owner_user_id

    and o.onboarding_id = #{onboardingId}
    and o.linked_user_id = #{linkedUserId}

        and (o.employee_name like concat('%', #{keyword}, '%')
            or o.phone_number like concat('%', #{keyword}, '%')
            or o.position_name like concat('%', #{keyword}, '%')
            or d.dept_name like concat('%', #{keyword}, '%')
            or o.company_name like concat('%', #{keyword}, '%')
            or o.dept_level1_name like concat('%', #{keyword}, '%')
            or o.dept_level2_name like concat('%', #{keyword}, '%')
            or o.dept_level3_name like concat('%', #{keyword}, '%')
            or o.store_name like concat('%', #{keyword}, '%'))

    and o.status = #{status}
    and o.target_dept_id = #{targetDeptId}
    and o.target_store_id = #{targetStoreId}

        and o.employee_category = #{employeeCategory}

    and o.owner_user_id = #{ownerUserId}

        and o.expected_entry_date >= #{expectedEntryDateFrom}


        and o.expected_entry_date <= #{expectedEntryDateTo}

    ${params.dataScope}

order by o.expected_entry_date asc, o.onboarding_id desc

select coalesce(sum(case
           when o.expected_entry_date >= #{summaryDate}
            and o.expected_entry_date < date_add(#{summaryDate}, interval 1 day)
           then 1 else 0 end), 0) as today_arrival_count,
       coalesce(sum(case when o.status = 'READY' then 1 else 0 end), 0) as pending_confirm_count,
       coalesce(sum(case when o.account_risk_code is not null
            and trim(o.account_risk_code) <> '' then 1 else 0 end), 0)
            as account_configuration_risk_count
from hr_onboarding o
join sys_dept d on d.dept_id = o.target_dept_id

    and o.onboarding_id = #{onboardingId}

        and (o.employee_name like concat('%', #{keyword}, '%')
            or o.phone_number like concat('%', #{keyword}, '%')
            or o.position_name like concat('%', #{keyword}, '%')
            or d.dept_name like concat('%', #{keyword}, '%')
            or o.company_name like concat('%', #{keyword}, '%')
            or o.dept_level1_name like concat('%', #{keyword}, '%')
            or o.dept_level2_name like concat('%', #{keyword}, '%')
            or o.dept_level3_name like concat('%', #{keyword}, '%')
            or o.store_name like concat('%', #{keyword}, '%'))

    and o.status = #{status}
    and o.target_dept_id = #{targetDeptId}
    and o.target_store_id = #{targetStoreId}

        and o.employee_category = #{employeeCategory}

    and o.owner_user_id = #{ownerUserId}

        and o.expected_entry_date >= #{expectedEntryDateFrom}


        and o.expected_entry_date <= #{expectedEntryDateTo}

    ${params.dataScope}

select task.onboarding_id, task.onboarding_no, task.employee_name, task.phone_number_masked, task.target_dept_id, task.target_store_id, task.target_post_id, task.company_name, task.dept_level1_name, task.dept_level2_name, task.dept_level3_name, task.store_name, task.position_name, task.employee_category, task.expected_entry_date, task.status, task.owner_user_id, task.owner_name, task.version, task.account_risk_code, task.readiness_missing_count, case when task.readiness_missing_count = 0 and task.derived_blocking_count = 0 then 1 else 0 end as mark_ready_allowed from ( select o.onboarding_id, o.onboarding_no, o.employee_name, case when o.phone_number is null then null when o.phone_number = '' then '' when char_length(o.phone_number) <= 7 then repeat('*', char_length(o.phone_number)) else concat(left(o.phone_number, 3), repeat('*', char_length(o.phone_number) - 7), right(o.phone_number, 4)) end as phone_number_masked, o.target_dept_id, o.target_store_id, o.target_post_id, o.company_name, o.dept_level1_name, o.dept_level2_name, o.dept_level3_name, o.store_name, o.position_name, o.employee_category, o.expected_entry_date, o.status, o.owner_user_id, owner.nick_name as owner_name, o.version, o.account_risk_code, (case when nullif(trim(o.employee_name), '') is null then 1 else 0 end + case when nullif(trim(o.phone_number), '') is null then 1 else 0 end + case when o.expected_entry_date is null then 1 else 0 end + case when o.target_dept_id is null then 1 else 0 end + case when o.target_post_id is null then 1 else 0 end + case when nullif(trim(o.employee_category), '') is null then 1 else 0 end + case when o.owner_user_id is null then 1 else 0 end + case when o.target_store_id is null then 1 else 0 end + case when nullif(trim(o.job_grade), '') is null then 1 else 0 end + case when o.direct_supervisor_user_id is null then 1 else 0 end + case when nullif(trim(o.sex), '') is null then 1 else 0 end + case when nullif(trim(o.id_type), '') is null then 1 else 0 end + case when nullif(trim(o.id_number), '') is null then 1 else 0 end + case when nullif(trim(o.registered_residence), '') is null then 1 else 0 end + case when nullif(trim(o.current_address), '') is null then 1 else 0 end + case when nullif(trim(o.work_location), '') is null then 1 else 0 end) as readiness_missing_count, (case when nullif(trim(o.company_name), '') is null then 1 else 0 end + case when (nullif(trim(o.dept_level1_name), '') is not null or nullif(trim(o.dept_level2_name), '') is not null or nullif(trim(o.dept_level3_name), '') is not null) and nullif(trim(o.department_supervisor), '') is null then 1 else 0 end + case when o.target_store_id is not null and nullif(trim(o.store_name), '') is null then 1 else 0 end + case when o.target_post_id is not null and nullif(trim(o.position_name), '') is null then 1 else 0 end) as derived_blocking_count from hr_onboarding o join sys_dept d on d.dept_id = o.target_dept_id left join sys_user owner on owner.user_id = o.owner_user_id
and o.expected_entry_date >= #{summaryDate} and o.expected_entry_date < date_add(#{summaryDate}, interval 1 day) and o.onboarding_id = #{onboardingId}
and (o.employee_name like concat('%', #{keyword}, '%') or o.phone_number like concat('%', #{keyword}, '%') or o.position_name like concat('%', #{keyword}, '%') or d.dept_name like concat('%', #{keyword}, '%') or o.company_name like concat('%', #{keyword}, '%') or o.dept_level1_name like concat('%', #{keyword}, '%') or o.dept_level2_name like concat('%', #{keyword}, '%') or o.dept_level3_name like concat('%', #{keyword}, '%') or o.store_name like concat('%', #{keyword}, '%'))
and o.status = #{status} and o.target_dept_id = #{targetDeptId} and o.target_store_id = #{targetStoreId}
and o.employee_category = #{employeeCategory}
and o.owner_user_id = #{ownerUserId}
and o.expected_entry_date >= #{expectedEntryDateFrom}
and o.expected_entry_date <= #{expectedEntryDateTo}
${params.dataScope}
) task order by task.expected_entry_date asc, task.onboarding_id desc

select o.* from hr_onboarding o join sys_dept d on d.dept_id = o.target_dept_id where o.linked_user_id in
#{userId}
${query.params.dataScope} order by o.linked_user_id asc, o.onboarding_id desc

select o.*
from hr_onboarding o



            or o.phone_number = #{phone}
            or o.id_number = #{idNumber}
            or o.employee_no = #{employeeNo}


    where 1 = 0

order by o.onboarding_id desc

select o.*
from hr_onboarding o
join sys_dept d on d.dept_id = o.target_dept_id

o.onboarding_id <> #{query.onboardingId}


        and (

                or o.phone_number = #{phone}
                or o.id_number = #{idNumber}
                or o.employee_no = #{employeeNo}

        )

    and 1 = 0

${query.params.dataScope}

order by o.onboarding_id desc

select distinct o.* from hr_onboarding o join sys_dept d on d.dept_id=o.target_dept_id
where (


    or o.phone_number=#{identity.phoneNumber}
    or o.id_number=#{identity.idNumber}
    or o.employee_no=#{identity.employeeNo}

)
${query.params.dataScope}
order by o.onboarding_id desc

select o.onboarding_id, o.status
from hr_onboarding o FORCE INDEX (PRIMARY)
where o.status in ('DRAFT', 'READY')


        and (

                or o.phone_number = #{phone}
                or o.id_number = #{idNumber}
                or o.employee_no = #{employeeNo}

        )

    and 1 = 0

order by o.onboarding_id asc
for update
